import{c as a,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const r="/assets/zh-cn_image_0000001487548198.zFxNrLCp.png",l="/assets/zh-cn_image_0000001538108293.DEM9tmYp.png",u=JSON.parse('{"title":"MrgSort","description":"","frontmatter":{},"headers":[{"level":1,"title":"MrgSort","slug":"mrgsort"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/排序组合（ISASI）/MrgSort.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/排序组合（ISASI）/MrgSort.md"}'),o={name:"api/SIMD-API/基础API/Memory矢量计算/排序组合（ISASI）/MrgSort.md"};function p(i,t,c,d,h,g){return s(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="mrgsort" tabindex="-1">MrgSort <a class="header-anchor" href="#mrgsort" aria-label="Permalink to &quot;MrgSort&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>√</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>将已经排好序的最多4条队列，合并排列成1条队列，结果按照score域由大到小排序。</p><p>MrgSort指令处理的数据一般是经过Sort32指令处理后的数据，也就是Sort32指令的输出，队列的结构如下所示：</p><ul><li><p>数据类型为float，每个结构占据8Bytes。</p><p><img src="'+r+'" alt=""></p></li><li><p>数据类型为half，每个结构也占据8Bytes，中间有2Bytes保留。</p><p><img src="'+l+`" alt=""></p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void MrgSort(const LocalTensor&lt;T&gt;&amp; dst, const MrgSortSrcList&lt;T&gt;&amp; src, const MrgSort4Info&amp; params)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>Ascend 950PR/Ascend 950DT，支持的数据类型为：half/float Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：half/float Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：half/float Atlas 200I/500 A2 推理产品，支持的数据类型为：half/float</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，存储经过排序后的数据。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，4个队列，并且每个队列都已经排好序，类型为MrgSortSrcList结构体，定义如下： &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen1546714181992&quot;&gt;template &lt;typename T&gt; struct MrgSortSrcList { <strong>aicore</strong> MrgSortSrcList() {} <strong>aicore</strong> MrgSortSrcList(const LocalTensor&lt;T&gt;&amp; src1In, const LocalTensor&lt;T&gt;&amp; src2In, const LocalTensor&lt;T&gt;&amp; src3In, const LocalTensor&lt;T&gt;&amp; src4In) { src1 = src1In[0]; src2 = src2In[0]; src3 = src3In[0]; src4 = src4In[0]; } LocalTensor&lt;T&gt; src1; // 第一个已经排好序的队列 LocalTensor&lt;T&gt; src2; // 第二个已经排好序的队列 LocalTensor&lt;T&gt; src3; // 第三个已经排好序的队列 LocalTensor&lt;T&gt; src4; // 第四个已经排好序的队列 };&lt;/pre&gt; 源操作数的数据类型与目的操作数保持一致。src1、src2、src3、src4类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。LocalTensor的起始地址需要8字节对齐。</td></tr><tr><td>params</td><td>输入</td><td>排序所需参数，类型为MrgSort4Info结构体。 具体定义请参考\${INSTALL_DIR}/include/ascendc/basic_api/interface/kernel_struct_proposal.h，\${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。 参数说明请参考表3。</td></tr></tbody></table><p><strong>表 3</strong> MrgSort4Info参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>elementLengths</td><td>四个源队列的长度（8Bytes结构的数目），类型为长度为4的uint16_t数据类型的数组，理论上每个元素取值范围[0, 4095]，但不能超出UB的存储空间。</td></tr><tr><td>ifExhaustedSuspension</td><td>某条队列耗尽后，指令是否需要停止，类型为bool，默认false。</td></tr><tr><td>validBit</td><td>有效队列个数，取值如下：3：前两条队列有效7：前三条队列有效15：四条队列全部有效</td></tr><tr><td>repeatTimes</td><td>迭代次数，每一次源操作数和目的操作数跳过四个队列总长度。取值范围：repeatTimes∈[1,255]。 repeatTimes参数生效是有条件的，需要同时满足以下四个条件：src包含四条队列并且validBit=15四个源队列的长度一致四个源队列连续存储ifExhaustedSuspension = False</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>当存在score[i]与score[j]相同时，如果i&gt;j，则score[j]将首先被选出来，排在前面。</li><li>每次迭代内的数据会进行排序，不同迭代间的数据不会进行排序。</li><li>需要注意此函数排序的队列非region proposal结构。</li><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>完整使用样例请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/mrg_sort" target="_blank" rel="noreferrer">MrgSort样例</a>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 对8个已排好序的队列进行合并排序，repeatTimes = 2，数据连续存放</span></span>
<span class="line"><span>// 每个队列包含32个(score,index)的8Bytes结构</span></span>
<span class="line"><span>// 最后输出对score域的256个数完成排序后的结果</span></span>
<span class="line"><span>AscendC::MrgSort4Info params;</span></span>
<span class="line"><span>params.elementLengths[0] = 32;</span></span>
<span class="line"><span>params.elementLengths[1] = 32;</span></span>
<span class="line"><span>params.elementLengths[2] = 32;</span></span>
<span class="line"><span>params.elementLengths[3] = 32;</span></span>
<span class="line"><span>params.ifExhaustedSuspension = false;</span></span>
<span class="line"><span>params.validBit = 0b1111;</span></span>
<span class="line"><span>params.repeatTimes = 2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::MrgSortSrcList&lt;float&gt; srcList;</span></span>
<span class="line"><span>srcList.src1 = workLocal[0];</span></span>
<span class="line"><span>srcList.src2 = workLocal[64]; // workLocal为float类型，每个队列占据256Bytes空间</span></span>
<span class="line"><span>srcList.src3 = workLocal[128];</span></span>
<span class="line"><span>srcList.src4 = workLocal[192];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>AscendC::MrgSort&lt;float&gt;(dstLocal, srcList, params);</span></span>
<span class="line"><span>outQueueDst.EnQue&lt;float&gt;(dstLocal);</span></span>
<span class="line"><span>outQueueDst.FreeTensor(dstLocal);</span></span></code></pre></div>`,23)])])}const b=a(o,[["render",p]]);export{u as __pageData,b as default};
